    targets = [("cwd", "coproducer_probe_io.tmp")]
    targets.append(("home", os.path.join(os.path.expanduser("~"), "coproducer_probe_io.tmp")))
    for d in (dirs or []):
        targets.append((d, os.path.join(d, "coproducer_probe_io.tmp")))
