# ---- L0 encode_sysex
def encode_sysex(data: list[int]) -> Result:
    """Pack bytes into 7-bit form: each group of up to 7 bytes becomes a header byte plus the low 7 bits.

    Header bit i holds the top bit of byte i of the group.
    Errors: E_ARG when data is not a list of integers from 0 to 255.
    """
    if not isinstance(data, list) or any(type(b) is not int or b < 0 or b > 255 for b in data):
        return fail("E_ARG", "data must be a list of integers from 0 to 255")
    out = []
    for i in range(0, len(data), 7):
        group = data[i:i + 7]
        head = 0
        for j, b in enumerate(group):
            head |= (b >> 7) << j
        out.append(head)
        out.extend(b & 0x7F for b in group)
    return ok(out)


# ---- L0 decode_sysex
def decode_sysex(data: list[int]) -> Result:
    """Unpack 7-bit SysEx data (groups of up to 8) back into bytes.

    Errors: E_ARG when a value is above 127 or the final group has a header but no data.
    """
    if not isinstance(data, list) or any(type(b) is not int or b < 0 or b > 127 for b in data):
        return fail("E_ARG", "data must be a list of integers from 0 to 127")
    out = []
    for i in range(0, len(data), 8):
        group = data[i:i + 8]
        if len(group) < 2:
            return fail("E_ARG", "truncated group: header byte without data")
        head = group[0]
        for j, b in enumerate(group[1:]):
            out.append(b | (((head >> j) & 1) << 7))
    return ok(out)


# ---- L0 split_frames
def split_frames(data: list[int], max_len: int) -> Result:
    """Split a byte list into consecutive chunks of at most max_len items.

    Errors: E_ARG when data is not a list or max_len is below 1.
    """
    if not isinstance(data, list) or type(max_len) is not int or max_len < 1:
        return fail("E_ARG", "data must be a list and max_len an integer of at least 1")
    return ok([data[i:i + max_len] for i in range(0, len(data), max_len)])


# ---- L0 build_frame
_PREFIX = [0xF0, 0x7D, 0x43, 0x50]


def build_frame(version: int, msg_type: int, req_id: int, seq: int, total: int, payload: list[int]) -> Result:
    """Build one SysEx frame: prefix, version, type, 14-bit request id, sequence, total, payload, checksum, F7.

    The checksum is the sum of every byte from version through the payload, masked to 7 bits.
    Errors: E_ARG for out-of-range fields or a payload byte above 127.
    """
    small = (version, msg_type)
    wide = (req_id, seq, total)
    if any(type(x) is not int or x < 0 or x > 127 for x in small):
        return fail("E_ARG", "version and msg_type must be 0 to 127")
    if any(type(x) is not int or x < 0 or x > 16383 for x in wide) or total < 1 or seq >= total:
        return fail("E_ARG", "req_id, seq, total must be 0 to 16383 with total >= 1 and seq < total")
    if not isinstance(payload, list) or any(type(b) is not int or b < 0 or b > 127 for b in payload):
        return fail("E_ARG", "payload must be a list of 7-bit integers")
    body = [version, msg_type, req_id >> 7, req_id & 0x7F, seq >> 7, seq & 0x7F, total >> 7, total & 0x7F] + payload
    return ok(_PREFIX + body + [sum(body) & 0x7F, 0xF7])


# ---- L0 parse_frame
# _PREFIX already defined above


def parse_frame(frame: list[int]) -> Result:
    """Validate a SysEx frame and return its fields.

    Errors: E_ARG with detail not_ours when the prefix differs, or bad_checksum when the checksum fails.
    """
    if not isinstance(frame, list) or any(type(b) is not int or b < 0 or b > 255 for b in frame):
        return fail("E_ARG", "frame must be a list of bytes")
    if len(frame) < 14 or frame[:4] != _PREFIX or frame[-1] != 0xF7:
        return fail("E_ARG", "not a coproducer frame", not_ours=True)
    if any(b > 127 for b in frame[1:-1]):
        return fail("E_ARG", "frame contains a byte above 127", not_ours=True)
    body = frame[4:-2]
    if (sum(body) & 0x7F) != frame[-2]:
        return fail("E_ARG", "bad checksum", bad_checksum=True)
    return ok({"version": body[0], "type": body[1], "req_id": (body[2] << 7) | body[3],
               "seq": (body[4] << 7) | body[5], "total": (body[6] << 7) | body[7], "payload": body[8:]})


# ---- L0 encode_body
def encode_body(name: str, data: dict) -> Result:
    """Turn an operation name and a JSON-friendly dict into message bytes: name, a 0x1F separator, compact JSON.

    Errors: E_ARG when name is empty or contains the separator, or data cannot be written as JSON.
    """
    if not isinstance(name, str) or not name or "\x1f" in name or not isinstance(data, dict):
        return fail("E_ARG", "name must be a non-empty string without 0x1F and data a dict")
    try:
        text = name + "\x1f" + json.dumps(data, separators=(",", ":"), ensure_ascii=True)
    except (TypeError, ValueError) as e:
        return fail("E_ARG", f"data is not JSON friendly: {e}")
    return ok(list(text.encode("utf-8")))


# ---- L0 decode_body
def decode_body(body: list[int]) -> Result:
    """Split message bytes into an operation name and its JSON dict.

    Errors: E_ARG when the bytes are not UTF-8, lack the separator, or the JSON is not an object.
    """
    try:
        text = bytes(body).decode("utf-8")
        name, sep, rest = text.partition("\x1f")
        data = json.loads(rest) if sep else None
    except (TypeError, ValueError) as e:
        return fail("E_ARG", f"undecodable body: {e}")
    if not sep or not name or not isinstance(data, dict):
        return fail("E_ARG", "body must be name, 0x1F, then a JSON object")
    return ok({"name": name, "data": data})


